#include "ui_comm.h"
#include <string.h>

static char g_aidogui_language[32] = "";
static char g_aidogui_theme[32] = "";

void _ui_set_language(const char * language)
{
    if(language == NULL) return;
    lv_snprintf(g_aidogui_language, sizeof(g_aidogui_language), "%s", language);
}

const char * _ui_get_language(void)
{
    return g_aidogui_language;
}

void _ui_switch_theme(const char * theme_id)
{
    if(theme_id == NULL) return;
    lv_snprintf(g_aidogui_theme, sizeof(g_aidogui_theme), "%s", theme_id);
}
